function useAction() {
    const [error, setError] = useState(''), [notice, setNotice] = useState(''), [reason, setReason] = useState(''), [operationId, setOperation] = useState(() => crypto.randomUUID());
    return { error, notice, reason, setReason: (v: string) => { setReason(v); setOperation(crypto.randomUUID()); }, perform: (fn: (base: {
            operationId: string;
            reason: string;
        }) => void) => {
            try {
                fn({ operationId, reason });
                setError('');
                setNotice('Payroll change saved.');
                setOperation(crypto.randomUUID());
            }
            catch (e) {
                setError((e as Error).message);
            }
        }, invalidate: () => setOperation(crypto.randomUUID()) };
}
function Reason({ a }: {
    a: ReturnType<typeof useAction>;
}) { return <Field label="Payroll change reason"><textarea className={fieldClass} maxLength={2000} value={a.reason} onChange={e => a.setReason(e.target.value)}/></Field>; }
function Setup() { const a = useAction(), s = usePayroll(), write = usePermission('payroll.manage'); return !s.settings.length ? <Panel title="Configure local payroll"><p>Create dedicated wages/contribution expense accounts, separate wage/tax/deduction/contribution liabilities and six editable pay items. PAYG defaults to reviewed manual withholding. The super helper calculates 12% of qualifying earnings explicitly reviewed for 2026–27.</p>{write && <><Reason a={a}/><button className={buttonClass} disabled={a.reason.trim().length < 3} onClick={() => a.perform(base => payrollClient.setupDefaults(base))}>Create payroll accounts and starter items</button></>}{a.error && <p role="alert">{a.error}</p>}</Panel> : null; }
const name = (s: PayrollState, employeeId: string) => s.employees.find(e => e.id === employeeId)?.name ?? employeeId;
function balance(s: PayrollState, e: Employee) {
    let annual = e.annualOpening, personal = e.personalOpening;
    const used = new Set<string>();
    for (const r of s.runs.filter(r => r.status === 'Posted'))
        for (const slip of r.slips.filter(p => p.employee.id === e.id)) {
            annual += slip.annualAccrual;
            personal += slip.personalAccrual;
            for (const lid of slip.leaveIds) {
                used.add(lid);
                const l = s.leave.find(l => l.id === lid);
                if (l?.type === 'Annual')
                    annual -= l.hours;
                if (l?.type === 'Personal')
                    personal -= l.hours;
            }
        }
    const approved = s.leave.filter(l => l.employeeId === e.id && l.status === 'Approved' && !used.has(l.id));
    return { annual, personal, reserved: approved.reduce((n, l) => n + l.hours, 0) };
}
