function dues(s: PayrollState, r: PayRun) {
    const sums = new Map<string, number>();
    const add = (id: string, n: number) => sums.set(id, round((sums.get(id) ?? 0) + n));
    for (const p of r.slips) {
        add(r.settings.netAccountId, p.totals.net);
        for (const l of p.lines) {
            if (['Tax', 'Deduction'].includes(l.item.category))
                add(l.item.accountId, l.amount);
            if (l.item.category === 'Employer contribution')
                add(l.item.liabilityAccountId, l.amount);
        }
    }
    return [...sums].map(([accountId, total]) => ({ accountId, total, paid: round(s.payments.filter(p => p.runId === r.id && p.accountId === accountId && p.status === 'Posted').reduce((n, p) => n + p.amount, 0)) }));
}
